import { RadialBarChart, RadialBar, Legend } from 'recharts';

const ProgressChart = ({ gains, investment }) => {
  const percent = investment > 0 ? Math.min((gains / investment) * 100, 100) : 0;

  const data = [
    {
      name: 'Progression',
      uv: percent,
      fill: percent >= 100 ? '#4caf50' : '#82ca9d',
    },
  ];

  return (
    <div style={{ textAlign: 'center' }}>
      <RadialBarChart
        width={300}
        height={200}
        innerRadius="80%"
        outerRadius="1000%"
        data={data}
        startAngle={180}
        endAngle={0}
      >
        <RadialBar minAngle={15} background clockWise dataKey="uv" />
        <Legend iconSize={10} layout="vertical" verticalAlign="middle" />
      </RadialBarChart>
      <p style={{ marginTop: '10px', fontWeight: 'bold', color: percent >= 100 ? '#4caf50' : '#333' }}>
        {percent >= 100 ? 'Objectif atteint !' : `${percent.toFixed(2)}%`}
      </p>
    </div>
  );
};

export default ProgressChart;
